# mix.sh DIR DUR NAME : voz_final.wav + musica.wav + sfx.wav -> mezcla.wav + NAME_musica_y_efectos.mp3
cd "$1" && ffmpeg -y -hide_banner -loglevel error -i voz_final.wav -i musica.wav -i sfx.wav -filter_complex "[0:a]apad=whole_dur=$2,asplit=2[v1][v2];[1:a]volume=1.25[m];[m][v2]sidechaincompress=threshold=0.02:ratio=4:attack=20:release=300[mc];[2:a]acompressor=threshold=0.06:ratio=4:attack=5:release=120:makeup=3,volume=.8[s];[v1][mc][s]amix=inputs=3:normalize=0,alimiter=limit=0.95,loudnorm=I=-14:TP=-1:LRA=11,aresample=44100" -t $2 mezcla.wav && \
ffmpeg -y -hide_banner -loglevel error -i musica.wav -i sfx.wav -filter_complex "[0:a]volume=1.1[m];[1:a]volume=.9[s];[m][s]amix=inputs=2:normalize=0,alimiter=limit=0.95" -c:a libmp3lame -b:a 192k "$3_musica_y_efectos.mp3" && echo mezcla ok
